            if (cptr.ld1so(u, $you_twoweap) && cptr.ld1so(flags, $flag_verbose))
                void cptr.sprintf(cptr.decay(withwhat), __s_with_s, yname(obj));
            pline(__s_s_divides_as_you_hit_it_s, Monnam(mon), cptr.decay(withwhat));
