/*
 * Special (passive) attacks on an attacking object by monsters done here.
 * Assumes the attack was successful.
 */
/**
 * C ref: uhitm.c:6127
 * @param {CPtr<struct monst>} mon
 * @param {CPtr<struct obj>} obj
 * @param {CPtr<struct attack>} mattk
 */
export function passive_obj(mon, obj, mattk) {
    let ptr = cptr.ldPtro(mon, $monst_data);
    let i;

    /* [this first bit is obsolete; we're not called with Null anymore] */
    /* if caller hasn't specified an object, use uwep, uswapwep or uarmg */
    if (!obj) {
        obj = (cptr.ld1so(u, $you_twoweap) && uswapwep.v && !rn2(2)) ? uswapwep.v : uwep.v;
        if (!obj && cptr.ld1uo(mattk, $attack_adtyp) == NHM.AD_ENCH)
            obj = uarmg.v;  /* no weapon? then must be gloves */
        if (!obj)
            return;  /* no object to affect */
    }

    /* if caller hasn't specified an attack, find one */
    if (!mattk) {
        for (i = 0; ; i++) {
            if (i >= NHM.NATTK)
                return;  /* no passive attacks */
            if (cptr.ld1uo2(ptr, i, $sizeof_attack, $permonst_mattk) == NHM.AT_NONE)
                break;  /* try this one */
        }
        mattk = cptr.add(cptr.add(ptr, $permonst_mattk), i, $sizeof_attack);
    }

    switch (cptr.ld1uo(mattk, $attack_adtyp)) {
        case NHM.AD_FIRE:
        if (!rn2(6) &&
                !(cptr.ldI32o(mon, $monst_mcan) & 1) &&
                !cptr.eq(
                    cptr.ldPtro(mon, $monst_data),
                    cptr.add(mons, NHC.PM_STEAM_VORTEX, $sizeof_permonst)
                )) {
            void erode_obj(obj, null, NHM.ERODE_BURN, NHM.EF_NONE);
        }
        break;
        case NHM.AD_ACID:
        if (!rn2(6)) {
            void erode_obj(obj, null, NHM.ERODE_CORRODE, NHM.EF_GREASE);
        }
        break;
        case NHM.AD_RUST:
        if (!(cptr.ldI32o(mon, $monst_mcan) & 1)) {
            void erode_obj(obj, null, NHM.ERODE_RUST, NHM.EF_GREASE);
        }
        break;
        case NHM.AD_CORR:
        if (!(cptr.ldI32o(mon, $monst_mcan) & 1)) {
            void erode_obj(obj, null, NHM.ERODE_CORRODE, NHM.EF_GREASE);
        }
        break;
        case NHM.AD_ENCH:
        if (!(cptr.ldI32o(mon, $monst_mcan) & 1)) {
            if (drain_item(obj, 1) &&
                    (cptr.ld1so((obj), $obj_where) == NHM.OBJ_INVENT) &&
                    ((cptr.ldI32o(obj, $obj_known) & 1) | 0 ||
                        cptr.ld1so(obj, $obj_oclass) == NHC.ARMOR_CLASS)) {
                pline(__s_s_less_effective, Yobjnam2(obj, __s_seem));
            }
            break;
        }
        // @FallThrough
        ;
        default:
        break;
    }

    if ((cptr.ld1so((obj), $obj_where) == NHM.OBJ_INVENT))
        update_inventory();
}

